// Signal Extraction — B2B Lead Enrichment v1.0.0
// Parses Apollo (person) + Clay (company) enrichment data.
// Falls back gracefully if one provider is missing.

const item = $input.item.json;

// --- Flatten key person fields from Apollo ---
const apolloData = item.person || item || {};
const firstName = apolloData.first_name || apolloData.firstName || '';
const title = apolloData.title || apolloData.headline || '';

// --- Flatten key company fields from Clay ---
const companyData = item.company || item.organization || item || {};
const companyName = companyData.name || companyData.company_name || item.company_domain || '';
const employeeCount = companyData.employee_count || companyData.employees || 0;
const industry = companyData.industry || companyData.category || '';

// --- Signal detection helpers ---
const now = DateTime.now();

function daysSince(dateStr) {
  if (!dateStr) return 9999;
  try {
    return Math.abs(now.diff(DateTime.fromISO(dateStr), 'days').days);
  } catch (e) {
    return 9999;
  }
}

// Signal 1: Funding round in last 90 days
const fundingDate = companyData.last_funding_date
  || companyData.funding_date
  || companyData.latest_funding_date
  || null;
const fundingRoundRecent = daysSince(fundingDate) <= 90;

// Signal 2: Job change — role start date within last 60 days
const jobStartDate = apolloData.job_start_date
  || apolloData.started_at
  || apolloData.employment_start_date
  || null;
const jobChangeDetected = daysSince(jobStartDate) <= 60;

// Signal 3: Tech stack shift — new tool added in last 30 days
const techAddedDate = companyData.tech_added_date
  || companyData.latest_tech_change_date
  || null;
const techStackShift = daysSince(techAddedDate) <= 30;

// Priority: highest signal wins (funding > job_change > tech_stack_shift > null)
let prioritySignal = null;
if (fundingRoundRecent) {
  prioritySignal = 'funding_round';
} else if (jobChangeDetected) {
  prioritySignal = 'job_change';
} else if (techStackShift) {
  prioritySignal = 'tech_stack_shift';
}

return {
  json: {
    lead_email: item.lead_email || apolloData.email || '',
    company_domain: item.company_domain || '',
    crm_contact_id: item.crm_contact_id || '',
    first_name: firstName,
    title,
    company_name: companyName,
    employee_count: employeeCount,
    industry,
    funding_round_recent: fundingRoundRecent,
    job_change_detected: jobChangeDetected,
    tech_stack_shift: techStackShift,
    priority_signal: prioritySignal,
    _apollo_raw: apolloData,
    _clay_raw: companyData
  }
};
